% [condition_table, condition_labels_lookup] = GenericTrialCounterbalancer_ConvertLabelsToIndices(args)
%
% Input:
%   condition_table             table of unique conditions, values in the columns used must be numeric or string
%   rules                       rules struct generated by GenericTrialCounterbalancer_InitializeRules (used to identify which fields to keep, does not need final overwrites)
%
% Output:
%   condition_table             reduced to the fields used by rules, converted to numeric indices
%   condition_labels_lookup     struct of lookups for numeric indices
%
function [condition_table, condition_labels_lookup] = GenericTrialCounterbalancer_ConvertLabelsToIndices(args)
arguments
    args.condition_table            table
    args.rules              (1,1)   struct
end

%% Verify that args with no defaults have been provided
requiredFields = ["condition_table","rules"];
missing = requiredFields(~isfield(args, requiredFields));
if ~isempty(missing)
    error("Missing required arguments: %s", strjoin(missing,", "))
end

%%
condition_table = table;

% for f = string(unique([fields(args.rules.order); fields(args.rules.perhalfcount)])')
for f = string(args.condition_table.Properties.VariableNames)
    [labels,~,condition_table.(f)] = unique(args.condition_table.(f));
    temp = struct(ID=(1:length(labels))', Label=labels);
    condition_labels_lookup.(f) = struct2table(temp);
end